          "gist": "Measures the fraction of candidate translation n-grams that appear in the reference translations.",
          "anchors": [],
          "is_first_principle": false
        },
        {
          "key": "brevity-penalty",
          "title": "Brevity Penalty",
          "gist": "Penalizes generated translations that are shorter than the reference to discourage gaming the metric.",
          "anchors": [],
          "is_first_principle": false
        },
        {
          "key": "reference-translation",
          "title": "Reference Translation",
          "gist": "Human-generated gold standard text used as the target for comparison.",
          "anchors": [],
          "is_first_principle": false
        },
        {
          "key": "geometric-mean",
          "title": "Geometric Mean",
          "gist": "Combines precision scores across multiple n-gram orders into a single aggregate value.",
